\begin{restatable}{prop}{propcentralized}[Centralization gain]
\label{prop:strict_improvements_from_centralization}
Assume $|\mathcal B|\geq2$.
For any $k\in \mathcal{S}, b\in \mathcal{B}$, the inspection-delay SLA under the extreme efficiency prioritizing city-budget policy is strictly better (shorter) than under the extreme efficiency prioritizing Borough-budget policy:
\begin{equation}
